/**
 * PASS 1 ON A PINNED MASTER SEED — the deterministic Pass-1 experiment (profile LIMBO-20).
 *
 * WHY A SECOND PASS-1 ARTIFACT. `outputs/simulation-results.json` (src/simulate.ts) drew its seeds
 * from crypto.randomBytes when this was written (from SIM_MASTER_SEED since 2026-09-26), stores only derived scalars (chi2, p, lag-1 z) and carries 8 edge targets:
 * nothing in it can be re-derived, it cannot be regenerated byte for byte, and it also holds the
 * Pass-2 cherry-pick screen whose rebuild is an open decision (L10) — so it is left exactly as
 * it is. This producer runs a SEPARATE Pass-1 experiment that meets the profile floor and is built to
 * be checked rather than believed:
 *   • every seed is derived from MASTER_SEED (recorded in the artifact), so the whole experiment is
 *     replayable byte for byte — `npm run pass1:check` regenerates it into outputs/run/ and diffs it;
 *   • it stores COUNTS, not verdicts — the 100-bin histogram of 2,000,000 draws, the integer
 *     sufficient statistics of the lag-1 and runs tests, and per target the number of wins out of
 *     1,000,000 rounds — so Step 23 re-derives every statistic from the rows;
 *   • it stores PREFIX counts (the first PASS1_PREFIX_DRAWS / PASS1_PREFIX_ROUNDS of every stream),
 *     which Step 23 recomputes on every `npm run verify` from the master seed, binding the rows to
 *     the declared seeds without a full replay on each run;
 *   • it carries no run metadata (no timestamp, no host, no timing).
 *
 * Output: outputs/pass1-grid.json (PF_EMIT=1 or no argument) | outputs/run/pass1-grid.json (--run).
 */

import * as fs from 'fs';
import * as path from 'path';
import { createHash } from 'node:crypto';

import { generateProvablyFairNumber } from './rng';
import {
  RANGE, CURSOR, RESULT_NUMERATOR, MAX_MULTIPLIER, MULTIPLIER_SCALE, HOUSE_EDGE,
  resultMultiplier, limboWin, targetToHundredths,
  PASS1_MASTER_SEED, PASS1_UNIFORMITY_DRAWS, PASS1_ROUNDS_PER_TARGET, PASS1_TARGETS,
  PASS1_PREFIX_DRAWS, PASS1_PREFIX_ROUNDS, PASS1_BINS, PASS1_EPOCH,
} from './config';

/** Deterministic seed pair for (stream, block): 32-hex server seed (operator format), 16-hex client seed. */
export function pass1Seeds(stream: string, block: number): { serverSeed: string; clientSeed: string } {
  const h = createHash('sha256').update(`${PASS1_MASTER_SEED}|${stream}|${block}`).digest('hex');
  return { serverSeed: h.slice(0, 32), clientSeed: h.slice(32, 48) };
}

/** Draw i of a stream: epochs of PASS1_EPOCH nonces, a fresh seed pair per epoch (like the real game). */
export function pass1Draw(stream: string, i: number): number {
  const { serverSeed, clientSeed } = pass1Seeds(stream, Math.floor(i / PASS1_EPOCH));
  return generateProvablyFairNumber(serverSeed, clientSeed, i % PASS1_EPOCH, CURSOR, RANGE);
}

export interface UniformityCounts {
  n: number; hist: number[];
  /** serial sufficient statistics on the bin index b in 0..BINS-1, integers */
  sumB: number; sumB2: number; sumLag: number;
  /** runs about k >= RANGE/2 */
  runs: number; above: number;
}

export function uniformityCounts(n: number): UniformityCounts {
  const per = RANGE / PASS1_BINS;
  const hist = new Array(PASS1_BINS).fill(0);
  let sumB = 0, sumB2 = 0, sumLag = 0, runs = 0, above = 0;
  let prevB = -1, prevHi: boolean | null = null;
  for (let i = 0; i < n; i++) {
    const k = pass1Draw('uniformity', i);
    const b = Math.floor(k / per);
    hist[b]++;
    sumB += b; sumB2 += b * b;
    if (prevB >= 0) sumLag += prevB * b;
    prevB = b;
    const hi = k >= RANGE / 2;
    if (hi) above++;
    if (hi !== prevHi) runs++;
    prevHi = hi;
  }
  return { n, hist, sumB, sumB2, sumLag, runs, above };
}

export function targetWins(target: number, n: number): number {
  let wins = 0;
  for (let i = 0; i < n; i++) if (limboWin(resultMultiplier(pass1Draw(`target:${target}`, i)), target)) wins++;
  return wins;
}

export function buildPass1Grid(): Record<string, unknown> {
  const uniformity = uniformityCounts(PASS1_UNIFORMITY_DRAWS);
  const prefix = uniformityCounts(PASS1_PREFIX_DRAWS);
  const targets = PASS1_TARGETS.map((t) => ({
    target: t,
    ci: targetToHundredths(t),
    rounds: PASS1_ROUNDS_PER_TARGET,
    wins: targetWins(t, PASS1_ROUNDS_PER_TARGET),
    prefixRounds: PASS1_PREFIX_ROUNDS,
    prefixWins: targetWins(t, PASS1_PREFIX_ROUNDS),
  }));
  return {
    experiment: 'LIQD limbo Pass 1 on a pinned master seed (profile LIMBO-20)',
    masterSeed: PASS1_MASTER_SEED,
    seedDerivation: 'sha256(masterSeed|stream|block): hex[0,32) = serverSeed, hex[32,48) = clientSeed; block = floor(i/epoch), nonce = i mod epoch',
    epoch: PASS1_EPOCH,
    model: { range: RANGE, cursor: CURSOR, resultNumerator: RESULT_NUMERATOR, maxMultiplier: MAX_MULTIPLIER, scale: MULTIPLIER_SCALE, houseEdge: HOUSE_EDGE },
    uniformity: { bins: PASS1_BINS, ...uniformity },
    uniformityPrefix: { bins: PASS1_BINS, ...prefix },
    targets,
  };
}

if (require.main === module) {
  const toRun = process.argv.includes('--run');
  const out = path.join(__dirname, '..', 'outputs', toRun ? 'run' : '', 'pass1-grid.json');
  fs.mkdirSync(path.dirname(out), { recursive: true });
  const t0 = Date.now();
  const body = JSON.stringify(buildPass1Grid(), null, 2) + '\n';
  fs.writeFileSync(out, body);
  const sha = createHash('sha256').update(body).digest('hex');
  console.log(`pass1-grid: wrote ${path.relative(path.join(__dirname, '..'), out)} sha256 ${sha} in ${((Date.now() - t0) / 1000).toFixed(1)} s`);
  if (toRun) {
    const committed = path.join(__dirname, '..', 'outputs', 'pass1-grid.json');
    const same = fs.existsSync(committed) && fs.readFileSync(committed, 'utf8') === body;
    fs.writeFileSync(path.join(__dirname, '..', 'outputs', 'run', 'pass1-grid-diff.json'), JSON.stringify({
      runtime: process.versions.node, reproducedByteForByte: same,
      note: 'the Pass-1 grid is all integers derived from the recorded master seed, so the regeneration must equal the committed artifact byte for byte',
    }, null, 2));
    console.log(`pass1-grid: regeneration vs committed artifact: ${same ? 'BYTE-IDENTICAL' : 'DIFFERS'}`);
    if (!same) process.exit(1);
  }
}
